      de: "Eine Treppenhalle: 16 × 20 m, eine 14-stufige Treppe, eine zentrale Säule, ein Zwischengeschoss und Glas.",
      it: "Una sala con scala: 16 × 20 m, una scala di 14 gradini, una colonna centrale, un soppalco e vetro.",
      es: "Una sala con escalera: 16 × 20 m, una escalera de 14 peldaños, una columna central, un entresuelo y cristal.",
      pt: "Uma sala de escadas: 16 × 20 m, uma escadaria de 14 degraus, uma coluna central, um mezanino e vidro.",
      zh: "楼梯大厅：16 × 20 米，14 级台阶，中央圆柱、夹层和玻璃。",
      ja: "階段のあるホール。16 × 20 m、14段の階段、中央の柱、メザニンとガラス。",
