      de: "Ein goldener Korridor: eine 7 × 46 m große Halle, Fischgrätparkett, leuchtende gewölbte Fenster, eine rote Stirnwand und Sonnenflecken auf dem Boden.",
      it: "Un corridoio d'oro: una sala 7 × 46 m, parquet a spina di pesce, luminose finestre ad arco, una parete rossa e macchie solari sul pavimento.",
      es: "Un pasillo dorado: una sala de 7 × 46 m, parquet en espiga, ventanas arqueadas luminosas, una pared de extremo rojo y manchas de sol en el suelo.",
      pt: "Um corredor dourado: uma sala de 7 × 46 m, parquet em espinha, janelas luminosas em arco, uma parede vermelha ao fundo e manchas de sol no chão.",
      zh: "金色走廊：7 × 46 米的大厅，人字形拼花地板、明亮的拱形窗、尽头的红色墙面和地板上的阳光斑点。",
      ja: "金色の回廊。7 × 46 mのホール、ヘリンボーンの寄木、光のアーチ窓、奥の赤い壁と床の日差しの斑点。",
      ko: "황금 복도: 7 × 46m 홀, 헤링본 쪽모이세공 마루, 빛나는 아치형 창, 붉은 끝 벽과 바닥의 햇빛 자국.",
