    founderNote: {
      fr: "Lakisa a été construit par un artiste qui sait ce que c'est de créer sans galerie pour montrer son travail. C'est une porte que nous ouvrons pour les prochains. Venez accrocher vos œuvres.",
      en: "Lakisa was built by an artist who knows what it is to make work with no gallery to show it in. This is a door we are opening for the next ones. Come and hang your work.",
      de: "Lakisa wurde von einem Künstler gebaut, der weiß, was es heißt, Werke zu machen, ohne eine Galerie, die sie zeigt. Dies ist eine Tür, die wir für die Nächsten öffnen. Kommen Sie und hängen Sie Ihr Werk auf.",
      it: "Lakisa è stata costruita da un artista che sa cosa significa fare opere senza una galleria che le esponga. Questa è una porta che apriamo per i prossimi. Vieni ad appendere la tua opera.",
      es: "Lakisa fue construida por un artista que sabe lo que es crear obras sin una galería que las exponga. Esta es una puerta que estamos abriendo para los próximos. Ven y cuelga tu obra.",
      pt: "A Lakisa foi construída por um artista que sabe o que é criar sem galeria para mostrar o seu trabalho. Esta é uma porta que estamos a abrir para os próximos. Venha pendurar as suas obras.",
      zh: "Lakisa 由一位艺术家创建，他深知在没有画廊展示作品的情况下进行创作意味着什么。这是我们为后来者打开的一扇门。来挂上您的作品吧。",
      ja: "Lakisaは、ギャラリーなしで作品を作ることがどういうことかを知るアーティストが作りました。これは、次の人たちのために開く扉です。作品を掛けに来てください。",
      ko: "Lakisa는 갤러리 없이 작품을 만드는 것이 어떤 것인지 아는 아티스트가 만들었습니다. 다음 사람들을 위해 여는 문입니다. 와서 작품을 걸어 보세요.",
      sw: "Lakisa ilijengwa na msanii anayejua maana ya kutengeneza kazi bila ghala ya kuionyesha. Huu ni mlango tunaofungua kwa wanaofuata. Njoo na uning'inize kazi yako.",
      ln: "Lakisa etongami na mosali oyo ayebi ndenge ezalaka kosala mosala na galerie te mpo na kolakisa yango. Oyo ezali ekotelo tofungolaka mpo na bato oyo bakoya na sima. Yaka mpe tia mosala na yo.",
    },
