      en: "Yes. Billing is off while we finish setting it up, so every plan and every tool is free to try. No card, no payment, no trial clock.",
      de: "Ja. Die Abrechnung ist deaktiviert, während wir sie einrichten, also sind jeder Tarif und jedes Tool kostenlos auszuprobieren. Keine Karte, keine Zahlung, kein Testzeitraum.",
