      zh: "是的。计费尚未开启，我们正在完成设置，因此每个方案和每个工具均可免费试用。无需银行卡，无需付款，没有试用倒计时。",
      ja: "はい。課金は、設定が終わるまでオフになっています。そのため、すべてのプランとツールは無料で試せます。カードも支払いも、試用期限もありません。",
      ko: "네. 결제는 설정이 완료될 때까지 꺼져 있으므로, 모든 요금제와 모든 도구를 무료로 사용해 볼 수 있습니다. 카드도, 결제도, 체험 기간도 없습니다.",
      sw: "Ndiyo. Malipo yamezimwa tunapomaliza kuyaweka, kwa hivyo kila mpango na kila zana ni bure kujaribu. Hakuna kadi, hakuna malipo, hakuna saa ya majaribio.",
