      fr: "Ouvrez « Mes œuvres » (/artworks) pour mettre en ligne les images de vos œuvres, avec leur titre, leur technique et leurs dimensions. La bibliothèque est partagée par toutes vos expositions : on met en ligne une fois, on accroche partout.",
