      it: "Apri «Le mie opere» (/artworks) per caricare le immagini delle tue opere con titolo, tecnica e dimensioni. La libreria è condivisa da tutte le tue mostre: carica una volta, appendi ovunque.",
      es: "Abre «Mis obras» (/artworks) para subir imágenes de tus obras con su título, técnica y dimensiones. La biblioteca se comparte en todas tus exposiciones: sube una vez, cuelga donde quieras.",
