    sectionArtworksStep4Text: {
      fr: "Sélectionnez les œuvres d'un mur et utilisez « Compose wall ». L'éditeur les accroche en une rangée à hauteur des yeux (1,50 m), espacées de 12 cm, la plus grande œuvre au centre. Si la rangée ne tient pas, il les répartit sur le mur. Toute la composition s'annule en une seule étape (Ctrl+Z), et vous pouvez ensuite déplacer chaque œuvre à la main.",
      en: "Select the works for a wall and use “Compose wall”. The editor hangs them in one row at eye level (1.50 m), 12 cm apart, the largest work in the centre. If the row does not fit, it packs them into the wall instead. The whole composition undoes in one step (Ctrl+Z), and you can still drag any work afterwards.",
      de: "Wählen Sie die Werke für eine Wand und verwenden Sie „Compose wall“. Der Editor hängt sie in einer Reihe auf Augenhöhe (1,50 m), 12 cm voneinander entfernt, das größte Werk in der Mitte. Wenn die Reihe nicht passt, verteilt er sie stattdessen auf der Wand. Die gesamte Komposition lässt sich in einem Schritt rückgängig machen (Strg+Z), und Sie können danach jedes Werk noch verschieben.",
      it: "Seleziona le opere per una parete e usa «Compose wall». L'editor le appende in una fila a livello degli occhi (1,50 m), a 12 cm di distanza, l'opera più grande al centro. Se la fila non entra, le distribuisce sulla parete. L'intera composizione si annulla in un solo passaggio (Ctrl+Z), e puoi ancora trascinare ogni opera dopo.",
      es: "Selecciona las obras para una pared y usa «Compose wall». El editor las cuelga en una fila a la altura de los ojos (1,50 m), a 12 cm de distancia, la obra más grande en el centro. Si la fila no cabe, las distribuye en la pared. Toda la composición se deshace en un paso (Ctrl+Z), y todavía puedes arrastrar cualquier obra después.",
      pt: "Selecione as obras de uma parede e use «Compose wall». O editor pendura-as numa fila à altura dos olhos (1,50 m), com 12 cm de distância, a maior obra ao centro. Se a fila não couber, distribui-as pela parede. Toda a composição se desfaz num só passo (Ctrl+Z), e depois pode ainda arrastar qualquer obra.",
      zh: "选择一面墙的作品并使用“Compose wall”。编辑器会将它们排成一行，挂在视线高度（1.50 米），间隔 12 厘米，最大的作品居中。如果一行放不下，则会将它们分布在墙面上。整个构图可一步撤销（Ctrl+Z），之后仍可拖动任何作品。",
      ja: "壁の作品を選択し、「Compose wall」を使います。エディタが目線の高さ（1.50 m）に一列に掛け、間隔は12 cm、最も大きな作品を中央にします。列が収まらない場合は、壁に分けて配置します。構成全体は1ステップで取り消せます（Ctrl+Z）。その後も作品はドラッグできます。",
      ko: "벽의 작품들을 선택하고 “Compose wall”을 사용하세요. 편집기가 눈높이(1.50m)에 12cm 간격으로 한 줄로 걸며, 가장 큰 작품이 가운데에 옵니다. 한 줄이 맞지 않으면 벽에 맞게 배치합니다. 전체 구성은 한 단계로 되돌릴 수 있고(Ctrl+Z), 이후에도 작품을 드래그할 수 있습니다.",
      sw: "Chagua kazi za ukuta na utumie “Compose wall”. Kihariri huziuning'iniza kwa mstari mmoja kwa urefu wa macho (m 1.50), kwa nafasi ya cm 12, kazi kubwa zaidi katikati. Mstari ukitoshea, huziweka ukutani badala yake. Muundo wote hutenduliwa kwa hatua moja (Ctrl+Z), na bado unaweza kuburuta kazi yoyote baadaye.",
      ln: "Pona misala ya mur mpe salela « Compose wall ». Mobongisi etiaka yango na molongo moko na bosanda ya miso (mɛtrɛ 1,50), na ntaka ya cm 12, mosala monene koleka na katikati. Soki molongo ekokani te, etiaka yango na mur na esika na yango. Molongo mobimba ekoki kozonga na etape moko (Ctrl+Z), mpe okoki nanu kobenda mosala moko na moko na sima.",
    },
