      ko: "설정에서 표시 이름, 자기소개, 프로필 사진을 변경하세요. 방문객이 전시 옆에서 보는 것입니다.",
      sw: "Kwenye Mipangilio, badilisha jina lako la kuonyesha, wasifu wako mfupi na picha yako ya wasifu. Hivi ndivyo wageni wanavyoona karibu na maonyesho yako.",
