      ja: "「自分の作品」（/artworks）はあなたのライブラリです。ここで作品のタイトルや詳細を編集すると、その作品が掛かっているすべての場所に反映されます。",
      ko: "“My artworks”(/artworks)는 라이브러리입니다. 작품의 제목이나 세부 정보를 그곳에서 수정하면, 작품이 걸린 모든 곳에 변경이 적용됩니다.",
