    sectionVisitStep1Text: {
      fr: "Trouvez-en une sur l'accueil, sur Explorer (/explore) ou dans les galeries publiques (/galleries), et ouvrez-la. Les expositions publiques s'ouvrent à tous ; une exposition à lien privé exige son lien, et une exposition à mot de passe demande d'abord son mot de passe.",
      en: "Find one on the homepage, on Explore (/explore) or in the public galleries (/galleries), and open it. Public exhibitions open for everyone; a private-link exhibition needs its link, and a password exhibition asks for its password first.",
      de: "Finden Sie eine auf der Homepage, auf „Entdecken“ (/explore) oder in den öffentlichen Galerien (/galleries), und öffnen Sie sie. Öffentliche Ausstellungen stehen allen offen; eine Ausstellung mit privatem Link braucht ihren Link, und eine Ausstellung mit Passwort fragt zuerst nach ihrem Passwort.",
      it: "Trovane una sulla homepage, su Esplora (/explore) o nelle gallerie pubbliche (/galleries), e aprila. Le mostre pubbliche sono aperte a tutti; una mostra con link privato ha bisogno del suo link, e una mostra con password chiede prima la sua password.",
      es: "Encuentra una en la página principal, en Explorar (/explore) o en las galerías públicas (/galleries), y ábrela. Las exposiciones públicas están abiertas a todos; una exposición de enlace privado necesita su enlace, y una exposición con contraseña pide primero su contraseña.",
      pt: "Encontre uma na página inicial, em Explorar (/explore) ou nas galerias públicas (/galleries), e abra-a. As exposições públicas abrem para todos; uma exposição de link privado precisa do seu link, e uma exposição com palavra-passe pede primeiro a sua palavra-passe.",
      zh: "在首页、探索（/explore）或公开画廊（/galleries）中找到一个展览并打开。公开的展览对所有人开放；私密链接展览需要其链接，密码展览会先要求输入密码。",
      ja: "ホームページ、「見る」（/explore）、公開ギャラリー（/galleries）で展示を見つけて開きます。公開展示は誰でも開けます。プライベートリンクの展示はリンクが必要で、パスワードの展示はまずパスワードをたずねます。",
      ko: "홈페이지, Explore(/explore), 공개 갤러리(/galleries)에서 찾아 여세요. 공개 전시는 누구나 열 수 있습니다. 비공개 링크 전시는 링크가 필요하고, 비밀번호 전시는 먼저 비밀번호를 묻습니다.",
      sw: "Tafuta moja kwenye ukurasa wa nyumbani, kwenye Explore (/explore) au kwenye maghala ya umma (/galleries), na uifungue. Maonyesho ya umma hufunguka kwa wote; onyesho la kiungo cha faragha linahitaji kiungo chake, na onyesho la nenosiri huuliza nenosiri lake kwanza.",
      ln: "Luka moko na page ya ndako, na Explore (/explore) to na ba galerie ya polele (/galleries), mpe fungola yango. Bimiseli ya polele efungolaka mpo na banso; bimiseli ya lien ya sekele esengaka lien na yango, mpe bimiseli ya mot de passe etunaka mot de passe na yango liboso.",
    },
