      it: "Imposti due prezzi: un prezzo massimo, indicato nell'annuncio, e un prezzo minimo, il prezzo più basso che accetti. Gli acquirenti negoziano tra i due. Le offerte sotto il tuo minimo sono rifiutate automaticamente.",
      es: "Estableces dos precios: un precio máximo, mostrado en el anuncio, y un precio mínimo, el precio más bajo que aceptas. Los compradores negocian entre los dos. Las ofertas por debajo de tu mínimo se rechazan automáticamente.",
      pt: "Define dois preços: um preço máximo, mostrado no anúncio, e um preço mínimo, o preço mais baixo que aceita. Os compradores negoceiam entre os dois. As ofertas abaixo do seu mínimo são recusadas automaticamente.",
