      it: "Scrivi le tue condizioni di vendita: spedizione inclusa o meno, quanto velocemente spedisci l'opera, resi accettati o meno, pagamento una tantum. Gli acquirenti le vedono nell'annuncio prima di acquistare.",
      es: "Escribe tus condiciones de venta: envío incluido o no, lo rápido que envías la obra, devoluciones aceptadas o no, pago único. Los compradores las ven en el anuncio antes de comprar.",
      pt: "Escreva as suas condições de venda: envio incluído ou não, rapidez de envio da obra, devoluções aceites ou não, pagamento de uma só vez. Os compradores veem-nas no anúncio antes de comprar.",
      zh: "写明您的销售条件：是否包含运费、发货速度、是否接受退货、一次性付款。买家在购买前会在商品页面上看到这些条件。",
