    sellerFeesTitle: {
      fr: "4. Les frais",
      en: "4. Fees",
      de: "4. Gebühren",
      it: "4. Commissioni",
      es: "4. Comisiones",
      pt: "4. As taxas",
      zh: "4. 费用",
      ja: "4. 手数料",
      ko: "4. 수수료",
      sw: "4. Ada",
      ln: "4. Ba frais",
    },
    sellerFeesText: {
      fr: "Lakisa garde une commission sur le prix convenu : 10 % en Découverte et Créateur, 5 % en Studio. Le prestataire de paiement (Flutterwave) prend environ 4,8 % par carte ou 3 % par Mobile Money en Ouganda. Pour un paiement manuel (Mobile Money ou virement, en dehors de la plateforme), il n'y a pas de frais de paiement : seule la commission Lakisa est déduite. Vous recevez le prix convenu moins la commission moins les frais de paiement. Vous voyez le calcul exact avant de confirmer une vente.",
      en: "Lakisa keeps a commission on the agreed price: 10% on Discovery and Creator, 5% on Studio. The payment provider (Flutterwave) takes about 4.8% by card or 3% by Mobile Money in Uganda. For a manual payment (Mobile Money or bank transfer, outside the platform), there is no payment fee: only the Lakisa commission is deducted. You receive the agreed price minus the commission minus the payment fee. You see the exact split before you confirm a sale.",
      de: "Lakisa behält eine Provision auf den vereinbarten Preis: 10% auf Discovery und Creator, 5% auf Studio. Der Zahlungsanbieter (Flutterwave) nimmt etwa 4,8% per Karte oder 3% per Mobile Money in Uganda. Für eine manuelle Zahlung (Mobile Money oder Banküberweisung, außerhalb der Plattform) fällt keine Zahlungsgebühr an: Es wird nur die Lakisa-Provision abgezogen. Sie erhalten den vereinbarten Preis abzüglich der Provision abzüglich der Zahlungsgebühr. Sie sehen die genaue Aufteilung, bevor Sie einen Verkauf bestätigen.",
      it: "Lakisa trattiene una commissione sul prezzo concordato: 10% su Discovery e Creator, 5% su Studio. Il fornitore di pagamento (Flutterwave) prende circa il 4,8% con carta o il 3% con Mobile Money in Uganda. Per un pagamento manuale (Mobile Money o bonifico bancario, al di fuori della piattaforma), non c'è nessuna commissione di pagamento: solo la commissione Lakisa viene detratta. Ricevi il prezzo concordato meno la commissione e meno la commissione di pagamento. Vedi la suddivisione esatta prima di confermare una vendita.",
      es: "Lakisa retiene una comisión sobre el precio acordado: 10% en Discovery y Creator, 5% en Studio. El proveedor de pagos (Flutterwave) cobra alrededor del 4,8% con tarjeta o el 3% con Mobile Money en Uganda. Para un pago manual (Mobile Money o transferencia bancaria, fuera de la plataforma), no hay comisión de pago: solo se deduce la comisión Lakisa. Recibes el precio acordado menos la comisión y menos la comisión de pago. Ves el desglose exacto antes de confirmar una venta.",
      pt: "A Lakisa fica com uma comissão sobre o preço acordado: 10% em Discovery e Creator, 5% em Studio. O prestador de pagamento (Flutterwave) cobra cerca de 4,8% por cartão ou 3% por Mobile Money no Uganda. Para um pagamento manual (Mobile Money ou transferência bancária, fora da plataforma), não há taxa de pagamento: só a comissão Lakisa é deduzida. Recebe o preço acordado menos a comissão menos a taxa de pagamento. Vê o cálculo exato antes de confirmar uma venda.",
      zh: "Lakisa 将从约定价格中收取佣金：Discovery 和 Creator 方案为 10%，Studio 方案为 5%。支付服务商（Flutterwave）按卡支付收取约 4.8%，在乌干达按 Mobile Money 收取 3%。对于手动支付（平台外的 Mobile Money 或银行转账），不收取支付费用：仅扣除 Lakisa 佣金。您将收到约定价格减去佣金再减去支付费用。确认销售前，您会看到确切的明细。",
      ja: "Lakisaは合意した価格から手数料を取ります。DiscoveryとCreatorは10%、Studioは5%です。決済事業者（Flutterwave）は、カードで約4.8%、ウガンダのMobile Moneyで3%を取ります。手動決済（プラットフォーム外のMobile Moneyまたは銀行振込）の場合、決済手数料はありません。Lakisaの手数料だけが差し引かれます。受け取るのは、合意した価格から手数料と決済手数料を引いた額です。販売を確定する前に、正確な内訳が表示されます。",
      ko: "Lakisa는 합의된 가격에서 수수료를 받습니다. Discovery와 Creator에서는 10%, Studio에서는 5%. 결제 업체(Flutterwave)는 카드로 약 4.8%, 우간다 Mobile Money로 3%를 받습니다. 수동 결제(Mobile Money 또는 은행 송금, 플랫폼 외부)의 경우 결제 수수료가 없습니다. Lakisa 수수료만 공제됩니다. 합의된 가격에서 수수료와 결제 수수료를 뺀 금액을 받습니다. 판매를 확정하기 전에 정확한 내역을 볼 수 있습니다.",
      sw: "Lakisa huweka kamisheni kwenye bei iliyokubaliwa: 10% kwenye Discovery na Creator, 5% kwenye Studio. Mtoa huduma wa malipo (Flutterwave) huchukua takriban 4.8% kwa kadi au 3% kwa Mobile Money nchini Uganda. Kwa malipo ya mikono (Mobile Money au uhamisho wa benki, nje ya jukwaa), hakuna ada ya malipo: kamisheni ya Lakisa tu ndiyo inayokatwa. Unapokea bei iliyokubaliwa ukiondoa kamisheni ukiondoa ada ya malipo. Unaona mgawanyo kamili kabla ya kuthibitisha uuzaji.",
      ln: "Lakisa ezwaka commission na motuya oyo bokokani: 10% na Discovery mpe Creator, 5% na Studio. Mobimisi ya kofuta (Flutterwave) ezwaka pene ya 4.8% na carte to 3% na Mobile Money na Uganda. Mpo na kofuta ya loboko (Mobile Money to virement ya banque, na libanda ya plateforme), frais ya kofuta ezali te: commission ya Lakisa kaka nde elongolamaka. Ozwaaka motuya oyo bokokani na kolongola commission mpe frais ya kofuta. Omonaka kokabola ya solo liboso ya kondima koteka.",
    },
