    sellerPaymentText: {
      fr: "L'acheteur paie Lakisa, pas vous directement. Lakisa garde l'argent et vous paie une fois la vente confirmée. Les paiements automatiques ouvrent bientôt : Flutterwave n'est pas encore branché. En attendant, l'acheteur peut vous payer directement par Mobile Money ou virement bancaire, et vous confirmez la réception à la main (voir point 7).",
      en: "The buyer pays Lakisa, not you directly. Lakisa holds the money and pays you once the sale is confirmed. Automatic payments open soon: Flutterwave is not connected yet. Until then, the buyer can pay you directly by Mobile Money or bank transfer, and you confirm receipt by hand (see point 7).",
      de: "Der Käufer zahlt Lakisa, nicht Sie direkt. Lakisa hält das Geld und zahlt Ihnen, sobald der Verkauf bestätigt ist. Automatische Zahlungen folgen bald: Flutterwave ist noch nicht angeschlossen. Bis dahin kann der Käufer Sie direkt per Mobile Money oder Banküberweisung bezahlen und Sie bestätigen den Empfang per Hand (siehe Punkt 7).",
      it: "L'acquirente paga Lakisa, non te direttamente. Lakisa trattiene i soldi e ti paga una volta che la vendita è confermata. I pagamenti automatici arriveranno presto: Flutterwave non è ancora collegato. Fino ad allora, l'acquirente può pagarti direttamente con Mobile Money o bonifico bancario, e tu confermi la ricezione a mano (vedi punto 7).",
      es: "El comprador paga a Lakisa, no a ti directamente. Lakisa guarda el dinero y te paga una vez que se confirma la venta. Los pagos automáticos llegarán pronto: Flutterwave aún no está conectado. Hasta entonces, el comprador puede pagarte directamente con Mobile Money o transferencia bancaria, y confirmas la recepción a mano (ver punto 7).",
      pt: "O comprador paga à Lakisa, não diretamente a si. A Lakisa guarda o dinheiro e paga-lhe quando a venda é confirmada. Os pagamentos automáticos abrem em breve: a Flutterwave ainda não está ligada. Até lá, o comprador pode pagar-lhe diretamente por Mobile Money ou transferência bancária, e confirma a receção à mão (ver o ponto 7).",
      zh: "买家向 Lakisa 付款，而不是直接向您付款。Lakisa 保管款项，待销售确认后向您付款。自动支付即将开通：Flutterwave 尚未接入。在此之前，买家可以直接通过 Mobile Money 或银行转账向您付款，您在订单中手动确认收款（见第 7 点）。",
      ja: "購入者はあなたに直接ではなく、Lakisaに支払います。Lakisaがお金を預かり、販売が確定したらあなたに支払います。自動決済はまもなく始まります。Flutterwaveはまだ接続されていません。それまでは、購入者はMobile Moneyまたは銀行振込であなたに直接支払うことができ、あなたは注文で手動で受領を確認します（ポイント7参照）。",
      ko: "구매자는 당신에게 직접이 아니라 Lakisa에 지불합니다. Lakisa가 돈을 보관하고 판매가 확정되면 당신에게 지불합니다. 자동 결제가 곧 시작됩니다. Flutterwave는 아직 연결되지 않았습니다. 그때까지 구매자는 Mobile Money나 은행 송금으로 직접 지불할 수 있으며, 당신이 직접 수령을 확인합니다(7번 참조).",
      sw: "Mnunuzi humlipa Lakisa, si wewe moja kwa moja. Lakisa hushikilia pesa na kukulipa mara uuzaji ukithibitishwa. Malipo ya kiotomatiki hufunguka hivi karibuni: Flutterwave haijaunganishwa bado. Hadi wakati huo, mnunuzi anaweza kukulipa moja kwa moja kwa Mobile Money au uhamisho wa benki, na unathibitisha kupokea kwa mkono (tazama nukta ya 7).",
      ln: "Mosombi afutaka Lakisa, yo te mobimba. Lakisa ebombaka mbongo mpe afutaka yo ntango koteka endimami. Kofuta ya momesano efungolaka na mikolo mike: Flutterwave ekangisami nanu te. Kino wana, mosombi akoki kofuta yo mobimba na Mobile Money to virement ya banque, mpe ondima koyamba na loboko (tala eteni 7).",
    },
