    sellerManualText: {
      fr: "En attendant le branchement de Flutterwave, un acheteur peut vous payer directement, en dehors de la plateforme : par Mobile Money (MTN ou Airtel) ou par virement bancaire. Indiquez votre numéro Mobile Money et vos coordonnées bancaires dans vos conditions de vente, pour que l'acheteur sache où payer. L'acheteur envoie ensuite la référence de la transaction, et vous confirmez la réception à la main dans vos Commandes : la commande passe alors en payée et l'œuvre est marquée vendue. Pour un paiement manuel, il n'y a pas de frais de paiement, seule la commission Lakisa est déduite. Le paiement automatique par Lakisa arrivera avec Flutterwave. Pour les abonnements, c'est pareil pour l'instant : le paiement est manuel et l'admin active votre offre à la main.",
      en: "Until Flutterwave is connected, a buyer can pay you directly, outside the platform: by Mobile Money (MTN or Airtel) or by bank transfer. Write your Mobile Money number and bank details in your sale conditions, so the buyer knows where to pay. The buyer then sends the transaction reference, and you confirm receipt by hand in your Orders: the order moves to paid and the work is marked sold. For a manual payment there is no payment fee, only the Lakisa commission is deducted. Automatic payment through Lakisa will come with Flutterwave. For subscriptions it is the same for now: payment is manual and the admin activates your plan by hand.",
      de: "Bis Flutterwave angeschlossen ist, kann ein Käufer Sie direkt außerhalb der Plattform bezahlen: per Mobile Money (MTN oder Airtel) oder per Banküberweisung. Schreiben Sie Ihre Mobile Money-Nummer und Bankdaten in Ihre Verkaufsbedingungen, damit der Käufer weiß, wo er bezahlen muss. Der Käufer sendet dann die Transaktionsreferenz, und Sie bestätigen den Erhalt in Ihren Bestellungen von Hand: Die Bestellung wechselt zu „bezahlt“ und das Werk wird als verkauft markiert. Bei einer manuellen Zahlung fällt keine Zahlungsgebühr an, nur die Lakisa-Provision wird abgezogen. Die automatische Zahlung über Lakisa kommt mit Flutterwave. Für Abonnements ist es vorerst dasselbe: Die Zahlung ist manuell und der Administrator aktiviert Ihren Tarif von Hand.",
      it: "Fino a quando Flutterwave è collegato, un acquirente può pagarti direttamente, al di fuori della piattaforma: con Mobile Money (MTN o Airtel) o tramite bonifico bancario. Scrivi il tuo numero Mobile Money e i dettagli bancari nelle tue condizioni di vendita, così l'acquirente sa dove pagare. L'acquirente invia poi il riferimento della transazione e tu confermi la ricezione a mano nei tuoi Ordini: l'ordine passa a pagato e l'opera viene segnata come venduta. Per un pagamento manuale non c'è nessuna commissione di pagamento, solo la commissione Lakisa viene detratta. Il pagamento automatico tramite Lakisa arriverà con Flutterwave. Per gli abbonamenti è lo stesso per ora: il pagamento è manuale e l'amministratore attiva il tuo piano a mano.",
      es: "Hasta que Flutterwave esté conectado, un comprador puede pagarte directamente, fuera de la plataforma: con Mobile Money (MTN o Airtel) o por transferencia bancaria. Escribe tu número de Mobile Money y tus datos bancarios en tus condiciones de venta, para que el comprador sepa dónde pagar. El comprador envía luego la referencia de la transacción, y confirmas la recepción a mano en tus Pedidos: el pedido pasa a pagado y la obra queda marcada como vendida. Para un pago manual no hay comisión de pago, solo se deduce la comisión Lakisa. El pago automático a través de Lakisa llegará con Flutterwave. Para las suscripciones es lo mismo por ahora: el pago es manual y el administrador activa tu plan a mano.",
      pt: "Enquanto a Flutterwave não estiver ligada, um comprador pode pagar-lhe diretamente, fora da plataforma: por Mobile Money (MTN ou Airtel) ou por transferência bancária. Escreva o seu número de Mobile Money e os seus dados bancários nas suas condições de venda, para o comprador saber onde pagar. O comprador envia depois a referência da transação, e confirma a receção à mão nas suas Encomendas: a encomenda passa a paga e a obra é marcada como vendida. Para um pagamento manual não há taxa de pagamento, só a comissão Lakisa é deduzida. O pagamento automático através da Lakisa chegará com a Flutterwave. Para as subscrições é o mesmo por agora: o pagamento é manual e o administrador ativa a sua oferta à mão.",
      zh: "在 Flutterwave 接入之前，买家可以直接在平台外向您付款：通过 Mobile Money（MTN 或 Airtel）或银行转账。请在销售条件中写明您的 Mobile Money 号码和银行信息，以便买家知道向哪里付款。买家随后发送交易参考号，您在订单中手动确认收款：订单转为已付款，作品标记为已售出。手动支付不收取支付费用，仅扣除 Lakisa 佣金。通过 Lakisa 的自动支付将随 Flutterwave 一同推出。目前订阅也是如此：支付为手动，管理员手动激活您的方案。",
      ja: "Flutterwaveが接続されるまで、購入者はプラットフォームの外であなたに直接支払うことができます。Mobile Money（MTNまたはAirtel）または銀行振込です。販売条件にMobile Moneyの番号と銀行情報を書いてください。購入者がどこに支払えばよいか分かります。購入者はその後、取引の参照番号を送り、あなたは注文で手動で受領を確認します。注文は支払済みになり、作品は売却済みと表示されます。手動決済では決済手数料はなく、Lakisaの手数料だけが差し引かれます。Lakisaを通した自動決済はFlutterwaveとともに始まります。サブスクリプションも今は同じです。支払いは手動で、管理者が手動でプランを有効にします。",
      ko: "Flutterwave가 연결될 때까지 구매자는 플랫폼 외부에서 직접 지불할 수 있습니다. Mobile Money(MTN 또는 Airtel)나 은행 송금으로요. 구매자가 어디로 지불해야 하는지 알 수 있도록 Mobile Money 번호와 은행 정보를 판매 조건에 적으세요. 구매자는 거래 참조 번호를 보내고, 당신은 주문에서 직접 수령을 확인합니다. 주문은 결제 완료로 이동하고 작품은 판매됨으로 표시됩니다. 수동 결제에는 결제 수수료가 없으며 Lakisa 수수료만 공제됩니다. Lakisa를 통한 자동 결제는 Flutterwave와 함께 제공됩니다. 구독도 지금은 마찬가지입니다. 결제는 수동이며 관리자가 직접 요금제를 활성화합니다.",
      sw: "Hadi Flutterwave iunganishwe, mnunuzi anaweza kukulipa moja kwa moja, nje ya jukwaa: kwa Mobile Money (MTN au Airtel) au kwa uhamisho wa benki. Andika namba yako ya Mobile Money na maelezo ya benki kwenye masharti yako ya uuzaji, ili mnunuzi ajue wapi kulipa. Mnunuzi kisha hutuma kumbukumbu ya muamala, na unathibitisha kupokea kwa mkono kwenye Maagizo yako: agizo huhamia kwenye kulipwa na kazi huwekwa alama kuwa imeuzwa. Kwa malipo ya mikono hakuna ada ya malipo, kamisheni ya Lakisa tu ndiyo inayokatwa. Malipo ya kiotomatiki kupitia Lakisa yatafika na Flutterwave. Kwa usajili ni vivyo hivyo kwa sasa: malipo ni ya mikono na msimamizi huamsha mpango wako kwa mkono.",
      ln: "Kino Flutterwave ekangisama, mosombi akoki kofuta yo mobimba, na libanda ya plateforme: na Mobile Money (MTN to Airtel) to na virement ya banque. Koma numéro na yo ya Mobile Money mpe makomi ya banque na mibeko na yo ya koteka, mpo na mosombi ayeba wapi kofuta. Mosombi atindaka na sima référence ya transaction, mpe ondima koyamba na loboko na Bakomande na yo: commande ekendeke na kofutama mpe mosala etiami lokola etekami. Mpo na kofuta ya loboko frais ya kofuta ezali te, commission ya Lakisa kaka nde elongolamaka. Kofuta ya momesano na Lakisa ekoya na Flutterwave. Mpo na ba abonnement ezali ndenge moko mpo na sikoyo: kofuta ezali ya loboko mpe moyangeli afungolaka plan na yo na loboko.",
    },
