      en: "The price you pay is the agreed price. You pay no extra fee. The seller pays the Lakisa commission and the payment fee.",
      de: "Der Preis, den Sie zahlen, ist der vereinbarte Preis. Sie zahlen keine zusätzliche Gebühr. Der Verkäufer zahlt die Lakisa-Provision und die Zahlungsgebühr.",
