      pt: "As ferramentas do dia a dia do mundo da arte, dentro do seu espaço de trabalho: tarife uma obra, mantenha o seu inventário, conheça os seus contactos, apresente e venda, e imprima os documentos que acompanham uma venda.",
      zh: "艺术世界的日常工具，尽在您的工作区：为作品定价、管理库存、了解联系人、展示与销售，并打印销售相关的文件。",
