    accessibilityDesc: {
      fr: "Rendez l'exposition ouverte à chaque visiteur. Rédigez des descriptions audio, des narrations d'artiste et de commissaire, des légendes et des transcriptions (en anglais et en français), écoutez-les lues à voix haute par les voix de votre navigateur, et mesurez le dossier à une vraie liste de contrôle d'accessibilité.",
      en: "Make the exhibition open to every visitor. Write audio descriptions, artist and curator narration, captions and transcripts (in English and French), hear them read aloud with your browser's own voices, and measure the pack against a real accessibility checklist.",
      de: "Machen Sie die Ausstellung für jeden Besucher offen. Schreiben Sie Audiobeschreibungen, Künstler- und Kuratorerzählungen, Bildunterschriften und Transkripte (auf Englisch und Französisch), hören Sie sie mit den eigenen Stimmen Ihres Browsers laut vorgelesen und messen Sie das Paket mit einer echten Checkliste für die Zugänglichkeit.",
      it: "Rendere la mostra aperta a ogni visitatore. Scrivere descrizioni audio, artista e curatrice narrazione, didascalie e trascrizioni (in inglese e francese), ascoltarli leggere ad alta voce con le proprie voci del browser, e misurare il pacchetto contro una vera lista di controllo di accessibilità.",
      es: "Haga la exposición abierta a cada visitante. Escribir descripciones de audio, artista y curador narración, leyendas y transcripciones (en inglés y francés), escucharlas leer en voz alta con las propias voces de su navegador, y medir el paquete contra una verdadera lista de verificación de accesibilidad.",
      pt: "Torne a exposição aberta a cada visitante. Escreva descrições de áudio, narrações de artista e de comissário, legendas e transcrições (em inglês e francês), ouça-as lidas em voz alta pelas vozes do seu navegador, e meça o conjunto com uma lista de verificação real de acessibilidade.",
      zh: "让展览向每一位访客开放。撰写音频描述、艺术家与策展人旁白、字幕和文字稿（英文和法文），用浏览器自带的语音收听朗读，并根据真实的无障碍清单衡量整套资料。",
      ja: "展示をすべての訪問者に開きます。音声ガイド、アーティストとキュレーターのナレーション、字幕と書き起こしを（英語とフランス語で）書き、ブラウザの音声で読み上げを聞き、実際のアクセシビリティチェックリストで内容を測ります。",
      ko: "전시를 모든 방문객에게 열어 주세요. 오디오 설명, 아티스트와 큐레이터 내레이션, 자막과 대본(영어와 프랑스어)을 작성하고, 브라우저의 음성으로 낭독되는 것을 듣고, 실제 접근성 체크리스트에 맞춰 패키지를 측정하세요.",
      sw: "Fanya onyesho liwe wazi kwa kila mgeni. Andika maelezo ya sauti, usimulizi wa msanii na mratibu, manukuu na nakala (kwa Kiingereza na Kifaransa), yasikilize yakisomwa kwa sauti na sauti za kivinjari chako mwenyewe, na upime kifurushi dhidi ya orodha halisi ya ukaguzi wa ufikivu.",
      ln: "Sala bimiseli epolele mpo na mopaya moko na moko. Koma ndimbola ya mongongo, lisolo ya mosali mpe ya commissaire, ba légende mpe makomi (na anglais mpe français), yoka yango etangamaka na mongongo ya navigateur na yo moko, mpe meka dossier na liste ya solo ya kotala ya bokoti.",
    },
