    aiArchitectDesc: {
      fr: "Planifiez une exposition à partir de vos propres œuvres. Le concept, l'accrochage, le choix de la salle, l'éclairage et les couleurs des murs sont calculés à partir de vos œuvres, dimensions, couleurs et des 40 modèles de galeries, aucun modèle nécessaire. Tout ce qui demanderait un modèle de langue est clairement indiqué et reste désactivé jusqu'à ce que vous connectiez un fournisseur d'IA.",
      en: "Plan a show from your own works. The concept, hang, room match, lighting and wall colours are computed from your artworks, dimensions, colours and the 40 gallery templates, no model needed. Anything that would need a language model is clearly marked and stays off until you connect an AI provider.",
      de: "Planen Sie eine Ausstellung aus Ihren eigenen Werken. Konzept, Hängung, Raumwahl, Beleuchtung und Wandfarben werden aus Ihren Werken, Abmessungen, Farben und den 40 Galerievorlagen berechnet, kein Modell erforderlich. Alles, was ein Sprachmodell benötigen würde, ist klar gekennzeichnet und bleibt ausgeschaltet, bis Sie einen KI-Anbieter anschließen.",
      it: "Organizza una mostra dalle tue opere. Il concetto, l'allestimento, la scelta della sala, l'illuminazione e i colori delle pareti sono calcolati dalle tue opere, dalle dimensioni, dai colori e dai 40 modelli di galleria, senza bisogno di modelli. Tutto ciò che richiederebbe un modello linguistico è chiaramente indicato e resta disattivato finché non colleghi un fornitore di IA.",
      es: "Planifica una exposición a partir de tus propias obras. El concepto, el montaje, la elección de la sala, la iluminación y los colores de las paredes se calculan a partir de tus obras, dimensiones, colores y las 40 plantillas de galería, sin necesidad de modelo. Todo lo que requeriría un modelo de lenguaje está claramente marcado y permanece desactivado hasta que conectes un proveedor de IA.",
      pt: "Planeie uma exposição a partir das suas próprias obras. O conceito, o penduramento, a escolha da sala, a iluminação e as cores das paredes são calculados a partir das suas obras, dimensões, cores e dos 40 modelos de galerias, sem necessidade de modelo. Tudo o que precisaria de um modelo de linguagem está claramente assinalado e fica desligado até ligar um fornecedor de IA.",
      zh: "根据您自己的作品规划展览。概念、悬挂、展厅匹配、灯光和墙面颜色均根据您的作品、尺寸、色彩和 40 个画廊模板计算得出，无需模型。任何需要语言模型的功能都会明确标注，并在您接入 AI 服务商之前保持关闭。",
      ja: "自分の作品から展示を計画します。コンセプト、展示方法、部屋の選択、照明、壁の色は、作品、サイズ、色、40のギャラリーテンプレートから計算されます。モデルは不要です。言語モデルが必要なものはすべて明確に示され、AIプロバイダーに接続するまでオフのままです。",
      ko: "내 작품으로 전시를 계획하세요. 컨셉, 걸기, 전시실 매칭, 조명, 벽 색상은 작품, 크기, 색상, 40개의 갤러리 템플릿에서 계산되며, 모델이 필요 없습니다. 언어 모델이 필요한 것은 명확히 표시되고 AI 제공업체를 연결하기 전까지 꺼져 있습니다.",
      sw: "Panga onyesho kutoka kazi zako mwenyewe. Dhana, upachikaji, ulinganifu wa chumba, mwanga na rangi za ukuta huhesabiwa kutoka kazi zako, vipimo, rangi na templeti 40 za ghala, hakuna modeli inayohitajika. Kitu chochote kinachohitaji modeli ya lugha kimewekwa alama wazi na hubaki kimezimwa hadi uunganishe mtoa huduma wa AI.",
      ln: "Bongisa bimiseli wuta misala na yo moko. Likanisi, kotiama, kopona ndako, moi mpe ba couleur ya bamir etangamaka wuta misala na yo, bonene, ba couleur mpe ba modèle 40 ya galerie, modèle moko te esengeli. Eloko nionso oyo esengaka modèle ya lokota elimbolami polele mpe etikali ekangami kino okangisa mobimisi ya AI.",
    },
