    aiAssistantDesc: {
      fr: "Posez des questions sur votre projet et obtenez des réponses tirées de vos vraies données (vos expositions, œuvres, salles et cadres) avec la source indiquée sous chaque réponse. Quand une question ne peut pas être répondue à partir des données et des règles, l'assistant le dit au lieu de deviner.",
      en: "Ask about your project and get answers from your real data (your exhibitions, artworks, rooms and frames) with the source shown under every answer. When a question cannot be answered from data and rules, the assistant says so instead of guessing.",
      de: "Fragen Sie nach Ihrem Projekt und erhalten Sie Antworten aus Ihren realen Daten (Ihre Ausstellungen, Werke, Räume und Rahmen) mit der Quelle unter jeder Antwort. Wenn eine Frage nicht aus Daten und Regeln beantwortet werden kann, sagt der Assistent dies, anstatt zu raten.",
      it: "Chiedi informazioni sul tuo progetto e ottieni risposte dai tuoi dati reali (le tue mostre, opere, sale e cornici) con la fonte mostrata sotto ogni risposta. Quando una domanda non può essere risposto da dati e regole, l'assistente lo dice invece di indovinare.",
      es: "Pregunte acerca de su proyecto y obtenga respuestas de sus datos reales (sus exposiciones, obras, salas y marcos) con la fuente mostrada bajo cada respuesta. Cuando una pregunta no puede ser contestada de datos y reglas, el asistente lo dice en lugar de adivinar.",
      pt: "Pergunte sobre o seu projeto e obtenha respostas a partir dos seus dados reais (as suas exposições, obras, salas e molduras) com a fonte indicada sob cada resposta. Quando uma pergunta não pode ser respondida a partir de dados e regras, o assistente diz isso em vez de adivinhar.",
      zh: "询问您的项目，并根据真实数据（您的展览、作品、展厅和画框）获得答案，每个答案下方都标明来源。当某个问题无法根据数据和规则回答时，助手会如实说明，而不会猜测。",
      ja: "プロジェクトについてたずねると、本物のデータ（展示、作品、部屋、額縁）から答えが返ります。すべての答えの下に出典が示されます。データとルールから答えられない質問には、推測せずにそう言います。",
      ko: "프로젝트에 대해 물어보고 실제 데이터(전시, 작품, 전시실, 액자)에서 답을 얻으세요. 모든 답변 아래에 출처가 표시됩니다. 데이터와 규칙으로 답할 수 없는 질문에는 어시스턴트가 추측 대신 그렇다고 말합니다.",
      sw: "Uliza kuhusu mradi wako na upate majibu kutoka data yako halisi (maonyesho yako, kazi, vyumba na fremu) huku chanzo kikionyeshwa chini ya kila jibu. Swali lisiloweza kujibiwa kutoka data na sheria, msaidizi husema hivyo badala ya kubahatisha.",
      ln: "Tuna na tina na projet na yo mpe zwa ba eyano wuta ba données na yo ya solo (bimiseli na yo, misala, bandako mpe ba cadre) na esika oyo ewutaki elakisami na se ya eyano moko na moko. Ntango motuna ekoki koyanolama te wuta ba données mpe mibeko, mosalisi elobaka bongo na esika ya kokanisa.",
    },
