    artInContextDesc: {
      fr: "Une œuvre, un parcours : mettez-la en ligne, photographiez-la, lisez ses couleurs, encadrez-la, accrochez-la dans une salle, disposez-la avec ses compagnes, placez-la dans la galerie 3D, publiez l'exposition, et faites-en la promotion. Chaque étape travaille sur la même fiche, donc rien n'est mis en ligne deux fois et rien ne se désynchronise.",
      en: "One artwork, one journey: upload it, photograph it, read its colours, frame it, hang it in a room, arrange it with its companions, place it in the 3D gallery, publish the show, and promote it. Every step works on the same record, so nothing is uploaded twice and nothing drifts out of sync.",
      de: "Ein Werk, eine Reise: Laden Sie es hoch, fotografieren Sie es, lesen Sie seine Farben, rahmen Sie es ein, hängen Sie es in einem Raum auf, arrangieren Sie es mit seinen Begleitwerken, platzieren Sie es in der 3D-Galerie, veröffentlichen Sie die Ausstellung und bewerben Sie es. Jeder Schritt arbeitet mit demselben Datensatz, sodass nichts zweimal hochgeladen wird und nichts aus dem Takt gerät.",
      it: "Un'opera, un viaggio: caricarla, fotografarla, leggere i suoi colori, incastrarla, appenderla in una sala, organizzarla con i suoi compagni, collocarla nella galleria 3D, pubblicarla e promuoverla. Ogni passo funziona sullo stesso record, quindi nulla viene caricato due volte e nulla si allontana dalla sincronizzazione.",
      es: "Una obra, un viaje: subirla, fotografiarla, leer sus colores, enmarcarla, colgarla en una sala, organizarla con sus compañeros, colocarla en la galería 3D, publicar el espectáculo y promoverlo. Cada paso funciona en el mismo registro, así que nada se carga dos veces y nada se deriva de la sincronización.",
      pt: "Uma obra, um percurso: carregue-a, fotografe-a, leia as suas cores, emoldure-a, pendure-a numa sala, disponha-a com as suas companheiras, coloque-a na galeria 3D, publique a exposição e promova-a. Cada passo trabalha na mesma ficha, por isso nada é carregado duas vezes e nada se dessincroniza.",
      zh: "一件作品，一段旅程：上传它、拍摄它、解读它的色彩、装裱它、挂在展厅中、与同伴一起布置、放入 3D 画廊、发布展览并推广它。每一步都作用于同一条记录，因此不会重复上传，也不会失去同步。",
      ja: "1つの作品、1つの旅。アップロードし、写真を撮り、色を読み、額装し、部屋に掛け、仲間と並べ、3Dギャラリーに置き、展示を公開して、宣伝します。すべてのステップは同じ記録で動くため、二度アップロードすることも、同期がずれることもありません。",
      ko: "작품 하나, 여정 하나: 업로드하고, 사진을 찍고, 색상을 읽고, 액자를 씌우고, 전시실에 걸고, 동료 작품과 함께 배치하고, 3D 갤러리에 놓고, 전시를 게시하고, 홍보하세요. 모든 단계가 같은 기록으로 작동하므로 두 번 업로드되는 것도, 동기화가 어긋나는 것도 없습니다.",
      sw: "Kazi moja, safari moja: ipakie, ipige picha, soma rangi zake, ibandike fremu, iuning'inize chumbani, ipange pamoja na wenzake, iiweke kwenye ghala ya 3D, chapisha onyesho, na uitangaze. Kila hatua hufanya kazi kwenye rekodi ileile, kwa hivyo hakuna kinachopakiwa mara mbili na hakuna kinachotoka kwenye ulinganifu.",
      ln: "Mosala moko, nzela moko: tia yango, beta yango foto, tanga ba couleur na yango, tia yango na cadre, tia yango na ndako, tia yango elongo na baninga na yango, tia yango na galerie ya 3D, bimisa bimiseli, mpe tangisa yango. Etape moko na moko esalaka na fiche moko, yango wana eloko moko te etiami mbala mibale mpe eloko moko te ebungaka na molongo.",
    },
