    collectionManagerDesc: {
      fr: "Chaque œuvre que vous possédez, dans toutes vos expositions, en un seul tableau. Recherchez, filtrez et triez, étiquetez les œuvres, suivez la disponibilité et l'emplacement, et gardez la provenance, les numéros d'inventaire, les constats d'état et les notes sur chaque pièce.",
      en: "Every artwork you own, across all your exhibitions, in one table. Search, filter and sort, tag works, track availability and location, and keep provenance, inventory numbers, condition reports and notes on each piece.",
      de: "Jedes Werk, das Sie besitzen, über alle Ihre Ausstellungen hinweg, in einer Tabelle. Suchen, filtern und sortieren, versehen Sie Werke mit Tags, verfolgen Sie Verfügbarkeit und Standort und bewahren Sie Herkunft, Inventarnummern, Zustandsberichte und Notizen zu jedem Stück auf.",
      it: "Ogni opera che possiedi, attraverso tutte le tue mostre, in un tavolo. Cercare, filtrare e ordinare, tag, tracciare la disponibilità e la posizione, e mantenere la provenienza, numeri di inventario, rapporti di stato e note su ogni pezzo.",
      es: "Cada obra que tienes, en todas tus exposiciones, en una mesa. Buscar, filtrar y ordenar, trabajos de etiquetas, seguimiento de disponibilidad y ubicación, y mantener la procedencia, números de inventario, informes de condiciones y notas en cada pieza.",
      pt: "Cada obra que possui, em todas as suas exposições, numa só tabela. Pesquise, filtre e ordene, marque obras, acompanhe a disponibilidade e a localização, e guarde a proveniência, os números de inventário, os relatórios de estado e as notas de cada peça.",
      zh: "您拥有的每一件作品，涵盖所有展览，尽在一张表格中。搜索、筛选和排序，为作品添加标签，跟踪可售性和位置，并保留每件作品的来源、库存编号、状况报告和备注。",
      ja: "所有するすべての作品を、すべての展示にわたって、1つの表に。検索、絞り込み、並べ替え、作品へのタグ付け、入手可能性と場所の追跡、来歴、在庫番号、状態報告、メモを各作品に残します。",
      ko: "소유한 모든 작품을 모든 전시에서 하나의 표로. 검색, 필터, 정렬하고, 작품에 태그를 지정하고, 이용 가능 여부와 위치를 추적하고, 각 작품의 출처, 인벤토리 번호, 상태 보고서, 메모를 보관하세요.",
      sw: "Kila kazi unayomiliki, kwenye maonyesho yako yote, kwenye jedwali moja. Tafuta, chuja na panga, weka lebo kwenye kazi, fuatilia upatikanaji na mahali, na uweke asili, namba za orodha, ripoti za hali na maelezo kwenye kila kipande.",
      ln: "Mosala moko na moko oyo ozali na yango, na bimiseli na yo nionso, na tableau moko. Luka, pona mpe bongisa na molongo, tia ba étiquette na misala, landa bomonani mpe esika, mpe bomba esika oyo ewutaki, ba numéro ya molongo, ba rapport ya ezaleli mpe ba note na mosala moko na moko.",
    },
