    digitalTwinDesc: {
      fr: "Mesurez une vraie salle une fois et gardez son jumeau numérique : dimensions exactes, finitions des murs et du sol, portes, fenêtres et l'emplacement de chaque œuvre. Comparez le plan au mètre ruban, obtenez un ordre d'installation, parcourez la salle en VR, et prévisualisez une œuvre sur votre propre mur en RA, ou sur une photo de celui-ci quand la RA n'est pas disponible.",
      en: "Measure a real room once and keep its digital twin: exact dimensions, wall and floor finishes, doors, windows and where each work hangs. Compare the plan against the tape measure, get an installation order, walk the room in VR, and preview a work on your own wall in AR, or on a photo of it when AR is not available.",
      de: "Messen Sie einen echten Raum einmal und behalten Sie seinen digitalen Zwilling: genaue Abmessungen, Wand- und Bodenoberflächen, Türen, Fenster und wo jedes Werk hängt. Vergleichen Sie den Plan mit dem Maßband, erhalten Sie einen Installationsauftrag, gehen Sie in VR durch den Raum und sehen Sie ein Werk an Ihrer eigenen Wand in AR oder auf einem Foto davon, wenn AR nicht verfügbar ist.",
      it: "Misurare una sala reale una volta e mantenere il suo gemello digitale: dimensioni esatte, pareti e pavimenti finiture, porte, finestre e dove ogni lavoro appende. Confrontare il piano contro la misura del nastro, ottenere un ordine di installazione, camminare la sala in VR, e in anteprima un lavoro sulla propria parete in AR, o su una foto di esso quando AR non è disponibile.",
      es: "Medir una sala real una vez y mantener su gemelo digital: dimensiones exactas, acabados de pared y suelo, puertas, ventanas y donde cada trabajo cuelga. Compare el plan contra la medida de cinta, obtenga una orden de instalación, pasee la sala en VR y prevea un trabajo en su propia pared en AR, o en una foto de ella cuando AR no está disponible.",
      pt: "Meça uma sala real uma vez e guarde o seu gémeo digital: dimensões exatas, acabamentos das paredes e do chão, portas, janelas e onde cada obra está pendurada. Compare o plano com a fita métrica, obtenha uma ordem de instalação, percorra a sala em VR, e pré-visualize uma obra na sua própria parede em RA, ou numa foto dela quando a RA não está disponível.",
      zh: "测量一次真实展厅并保留其数字孪生：精确尺寸、墙面和地面饰面、门窗，以及每件作品的悬挂位置。将平面图与卷尺对照，获得安装顺序，在 VR 中漫步展厅，并在 AR 中于自己的墙面上预览作品；AR 不可用时，可在墙面照片上预览。",
      ja: "本物の部屋を一度測り、デジタルツインを残します。正確なサイズ、壁と床の仕上げ、ドア、窓、各作品の掛かる場所。平面図をメジャーと比べ、設置の順番を得て、VRで部屋を歩き、自分の壁で作品をARでプレビューします。ARが使えないときは、その壁の写真でプレビューします。",
      ko: "실제 전시실을 한 번 측정하고 디지털 트윈을 보관하세요. 정확한 크기, 벽과 바닥 마감, 문, 창, 각 작품이 걸린 위치. 줄자로 계획과 비교하고, 설치 순서를 얻고, VR로 전시실을 거닐고, 내 벽에서 AR로 작품을 미리 보거나, AR이 안 될 때는 사진으로 보세요.",
      sw: "Pima chumba halisi mara moja na uweke pacha wake wa kidijitali: vipimo kamili, umaliziaji wa ukuta na sakafu, milango, madirisha na mahali kila kazi inapouning'inizwa. Linganisha mpango na kipimo cha tepi, pata mpangilio wa usakinishaji, tembea chumba kwa VR, na hakikisha kazi kwenye ukuta wako kwa AR, au kwenye picha yake wakati AR haipatikani.",
      ln: "Meka ndako ya solo mbala moko mpe bomba jumeau na yango ya numérique: bonene ya solo, ba finition ya mur mpe ya mabele, ba porte, ba fenetre mpe esika mosala moko na moko etiami. Kokokanisa plan na mètre, zwa molongo ya kotiama, tambola na ndako na VR, mpe mona mosala na mur na yo na AR, to na foto na yango ntango AR ekoki te.",
    },
