    marketplaceDesc: {
      fr: "Mettez une œuvre en vente, fixez son prix, et parlez à l'acheteur qui vous écrit. La demande est le chemin de la vente. Un visiteur écrit, vous répondez par e-mail, et vous convenez de la vente directement. Aucun paiement n'est encore pris sur Lakisa.",
      en: "Put a work up for sale, set its price, and talk to the buyer who asks about it. The inquiry is the sale path. A visitor writes, you reply by email, and you agree the sale directly. No payment is taken on Lakisa yet.",
      de: "Stellen Sie ein Werk zum Verkauf, legen Sie seinen Preis fest und sprechen Sie mit dem Käufer, der sich dafür interessiert. Die Anfrage ist der Weg zum Verkauf. Ein Besucher schreibt, Sie antworten per E-Mail und stimmen dem Verkauf direkt zu. Auf Lakisa wird noch keine Zahlung geleistet.",
      it: "Mettere un lavoro in vendita, impostare il suo prezzo, e parlare con l'acquirente che chiede di esso. L'indagine è il percorso di vendita. Un visitatore scrive, rispondete via e-mail e accettate la vendita direttamente. Nessun pagamento è ancora effettuato su Lakisa.",
      es: "Ponga un trabajo a la venta, establezca su precio, y hable con el comprador que pregunta sobre ello. La investigación es el camino de venta. Un visitante escribe, responde por correo electrónico, y usted acepta la venta directamente. Aún no se ha pagado Lakisa.",
      pt: "Coloque uma obra à venda, defina o seu preço e fale com o comprador que pergunta sobre ela. O pedido é o caminho da venda. Um visitante escreve, responde por e-mail e combinam a venda diretamente. Ainda não é feito nenhum pagamento na Lakisa.",
      zh: "将作品上架销售、定价，并与询问它的买家交谈。咨询就是销售路径。访客写信，您通过邮件回复，并直接商定销售。Lakisa 上尚未收取任何款项。",
      ja: "作品を出品し、価格を設定し、問い合わせてきた購入者と話します。問い合わせが販売への道です。訪問者が書き、あなたがメールで返信し、直接販売を決めます。Lakisaでの支払いはまだありません。",
      ko: "작품을 판매용으로 올리고, 가격을 정하고, 문의하는 구매자와 이야기하세요. 문의가 판매 경로입니다. 방문객이 글을 쓰고, 당신이 이메일로 답하고, 직접 판매에 합의합니다. 아직 Lakisa에서는 결제가 이루어지지 않습니다.",
      sw: "Weka kazi kwa kuuza, weka bei yake, na uzungumze na mnunuzi anayeuliza kuihusu. Swali ndilo njia ya uuzaji. Mgeni huandika, unajibu kwa barua pepe, na mnakubaliana uuzaji moja kwa moja. Hakuna malipo yanayochukuliwa kwenye Lakisa bado.",
      ln: "Tia mosala mpo na koteka, tia motuya na yango, mpe solola na mosombi oyo atunaka na tina na yango. Motuna nde nzela ya koteka. Mopaya akomaka, oyanolaka na email, mpe bokokanaka koteka mobimba. Kofuta moko te ezwami na Lakisa nanu.",
    },
