    mockupStudioDesc: {
      fr: "Accrochez votre œuvre sur un vrai mur avant même qu'elle quitte l'atelier. Choisissez une œuvre, choisissez une salle, réglez le cadre et la lumière, puis exportez une maquette prête à imprimer à envoyer à un acheteur ou une galerie.",
      en: "Hang your work on a real wall before it ever leaves the studio. Pick an artwork, choose a room, set the frame and the light, then export a print-ready mockup to send to a buyer or a gallery.",
      de: "Hängen Sie Ihr Werk an eine echte Wand, bevor es das Studio verlässt. Wählen Sie ein Werk, wählen Sie einen Raum, stellen Sie den Rahmen und das Licht ein, exportieren Sie dann ein druckfertiges Mockup, das Sie an einen Käufer oder eine Galerie senden.",
      it: "Impicca il tuo lavoro su un vero muro prima che lasci mai lo studio. Scegli un'opera, scegli una sala, imposta la cornice e la luce, quindi esporta un mockup pronto per inviare un acquirente o una galleria.",
      es: "Colga tu trabajo en una pared real antes de que salga del estudio. Escoge una obra, elige una sala, establece el marco y la luz, luego exporta una maqueta lista para enviar a un comprador o una galería.",
      pt: "Pendure a sua obra numa parede real antes mesmo de ela sair do estúdio. Escolha uma obra, escolha uma sala, regule a moldura e a luz, depois exporte uma maqueta pronta a imprimir para enviar a um comprador ou a uma galeria.",
      zh: "在作品离开工作室之前，先将其挂在真实的墙面上。挑选一件作品、选择一个房间、设定画框和灯光，然后导出可打印的效果图，发送给买家或画廊。",
      ja: "スタジオを出る前に、本物の壁に作品を掛けます。作品を選び、部屋を選び、額縁と光を設定し、印刷用のモックアップを書き出して、購入者やギャラリーに送ります。",
      ko: "스튜디오를 떠나기 전에 실제 벽에 작품을 걸어 보세요. 작품을 고르고, 전시실을 고르고, 액자와 빛을 설정한 뒤, 구매자나 갤러리에 보낼 인쇄용 목업을 내보내세요.",
      sw: "Ning'iniza kazi yako kwenye ukuta halisi kabla haijaondoka studio. Chagua kazi, chagua chumba, weka fremu na mwanga, kisha hamisha mfano tayari kwa uchapishaji ili kumtumia mnunuzi au ghala.",
      ln: "Tia mosala na yo na mur ya solo liboso etika studio. Pona mosala, pona ndako, tia cadre mpe moi, na sima bimisa maquette ebongi mpo na kobimisa mpo na kotinda na mosombi to galerie.",
    },
