    photographyLabDesc: {
      fr: "Redressez une photo de travers, recadrez au bord du papier, corrigez la lumière, et exportez un fichier propre pour votre catalogue ou un jury. Rien ici ne touche votre photo originale : chaque modification est un réglage, appliqué seulement à l'export.",
      en: "Straighten a crooked shot, crop to the paper's edge, fix the light, and export a clean file for your catalogue or a jury. Nothing here touches your original photo: every edit is a setting, applied only when you export.",
      de: "Begradigen Sie ein schiefes Foto, schneiden Sie es am Papierrand zu, korrigieren Sie das Licht und exportieren Sie eine saubere Datei für Ihren Katalog oder eine Jury. Nichts hier berührt Ihr Originalfoto: Jede Bearbeitung ist eine Einstellung, die nur beim Export angewendet wird.",
      it: "Raddrizza uno scatto storto, ritaglia fino al bordo della carta, correggi la luce ed esporta un file pulito per il tuo catalogo o una giuria. Qui nulla tocca la tua foto originale: ogni modifica è un'impostazione, applicata solo quando esporti.",
      es: "Endereza un tiro torcido, cosecha al borde del papel, fija la luz y exporta un archivo limpio para tu catálogo o un jurado. Nada aquí toca su foto original: cada edición es un ajuste, aplicado sólo cuando se exporta.",
      pt: "Endireite uma foto torta, recorte até à borda do papel, corrija a luz e exporte um ficheiro limpo para o seu catálogo ou um júri. Nada aqui toca na sua foto original: cada edição é uma definição, aplicada apenas quando exporta.",
      zh: "校正倾斜的照片、裁剪到纸张边缘、修正光线，并为目录或评审团导出干净的文件。这里不会改动您的原始照片：每项编辑都是一项设置，仅在导出时应用。",
      ja: "曲がった写真をまっすぐにし、紙の端で切り取り、光を補正し、カタログや審査員のためのきれいなファイルを書き出します。ここでは元の写真には何も触れません。すべての編集は設定で、書き出すときにだけ適用されます。",
      ko: "기울어진 사진을 바로잡고, 종이 가장자리에 맞춰 자르고, 빛을 고치고, 카탈로그나 심사위원용으로 깨끗한 파일을 내보내세요. 이곳에서는 원본 사진을 건드리지 않습니다. 모든 수정은 설정일 뿐이며 내보낼 때만 적용됩니다.",
      sw: "Nyosha picha iliyopinda, kata hadi ukingo wa karatasi, rekebisha mwanga, na hamisha faili safi kwa katalogi yako au juri. Hakuna kinachogusa picha yako ya asili hapa: kila hariri ni mpangilio, unaotumika tu unapohamisha.",
      ln: "Bongisa foto oyo egumbami, kata kino nsuka ya papier, bongisa moi, mpe bimisa fichier ya peto mpo na catalogue na yo to jury. Eloko moko te awa esimbi foto na yo ya liboso: mbongwana moko na moko ezali misalelo, esalamaka kaka ntango obimisaka.",
    },
