    presentSellDesc: {
      fr: "Une exposition publiée est déjà une salle de présentation : un lien, les œuvres au mur, le visiteur la parcourt. Partagez le lien, suivez les visites, relancez pendant que l'œuvre est encore fraîche dans leur esprit.",
      en: "A published exhibition is already a viewing room: one link, the works on the wall, the visitor walks through it. Share the link, watch the visits, follow up while the work is still fresh in their mind.",
      de: "Eine veröffentlichte Ausstellung ist bereits ein Ausstellungsraum: ein Link, die Werke an der Wand, der Besucher geht durch sie hindurch. Teilen Sie den Link, beobachten Sie die Besuche, fassen Sie nach, solange das Werk noch frisch in ihrem Kopf ist.",
      it: "Una mostra pubblicata è già una sala di visualizzazione: un link, le opere sul muro, il visitatore cammina attraverso di esso. Condividere il link, guardare le visite, seguire mentre il lavoro è ancora fresco nella loro mente.",
      es: "Una exposición publicada ya es una sala de visualización: un enlace, las obras en la pared, el visitante camina a través de ella. Comparte el enlace, mira las visitas, sigue mientras el trabajo todavía está fresco en su mente.",
      pt: "Uma exposição publicada já é uma sala de apresentação: um link, as obras na parede, o visitante percorre-a. Partilhe o link, acompanhe as visitas, faça seguimento enquanto a obra ainda está fresca na sua mente.",
      zh: "已发布的展览本身就是一个展示厅：一个链接，作品挂在墙上，访客漫步其中。分享链接、关注访问，并在作品仍在他们脑海中时跟进。",
      ja: "公開済みの展示は、すでにビューイングルームです。1つのリンク、壁の作品、訪問者は歩いて巡ります。リンクを共有し、訪問を見守り、作品がまだ心に新しいうちにフォローアップします。",
      ko: "게시된 전시는 이미 뷰잉 룸입니다. 하나의 링크, 벽의 작품, 방문객이 거닐어 봅니다. 링크를 공유하고, 방문을 지켜보고, 작품이 아직 마음에 생생할 때 후속 조치를 하세요.",
      sw: "Onyesho lililochapishwa tayari ni chumba cha kuonyesha: kiungo kimoja, kazi ukutani, mgeni huitembea. Shiriki kiungo, angalia ziara, fanya ufuatiliaji wakati kazi bado iko safi akilini mwao.",
      ln: "Bimiseli oyo ebimaki ezali kala ndako ya kolakisa: lien moko, misala na mur, mopaya atambolaka na kati. Kabola lien, tala bakoti, landa ntango mosala ezali nanu ya sika na makanisi na bango.",
    },
