    presentationDesignerDesc: {
      fr: "Transformez vos œuvres en une présentation qu'une galerie, un jury ou une foire peut ouvrir et comprendre en quelques minutes : une page de titre, vos œuvres avec légendes, votre biographie et votre projet, exportés en PDF.",
      en: "Turn your artworks into a presentation a gallery, a jury or a fair can open and understand in minutes: a title page, your works with captions, your biography and your project, exported as a PDF.",
      de: "Verwandeln Sie Ihre Werke in eine Präsentation, die eine Galerie, eine Jury oder eine Messe in wenigen Minuten öffnen und verstehen kann: eine Titelseite, Ihre Werke mit Bildunterschriften, Ihre Biografie und Ihr Projekt, exportiert als PDF.",
      it: "Trasforma le tue opere in una presentazione una galleria, una giuria o una fiera possono aprire e capire in pochi minuti: una pagina del titolo, i tuoi lavori con didascalie, la tua biografia e il tuo progetto, esportati in formato PDF.",
      es: "Convierta sus obras en una presentación una galería, un jurado o una feria puede abrir y entender en minutos: una página de título, sus obras con leyendas, su biografía y su proyecto, exportado como un PDF.",
      pt: "Transforme as suas obras numa apresentação que uma galeria, um júri ou uma feira pode abrir e compreender em minutos: uma página de título, as suas obras com legendas, a sua biografia e o seu projeto, exportados em PDF.",
      zh: "将您的作品变成一份演示文稿，画廊、评审团或艺博会可在几分钟内打开并理解：标题页、带说明的作品、您的简介和项目，导出为 PDF。",
      ja: "作品を、ギャラリー、審査員、フェアが数分で開いて理解できるプレゼンテーションにします。タイトルページ、説明付きの作品、経歴、プロジェクトをPDFで書き出します。",
      ko: "작품을 갤러리, 심사위원, 박람회가 몇 분 안에 열고 이해할 수 있는 프레젠테이션으로 바꾸세요. 표지, 설명이 있는 작품, 자기소개, 프로젝트를 PDF로 내보내기.",
      sw: "Geuza kazi zako kuwa wasilisho ambalo ghala, juri au maonyesho yanaweza kufungua na kuelewa kwa dakika: ukurasa wa kichwa, kazi zako zenye manukuu, wasifu wako na mradi wako, uliohamishwa kama PDF.",
      ln: "Bongola misala na yo na présentation oyo galerie, jury to foire ekoki kofungola mpe koyeba na miniti moke: page ya kombo, misala na yo na ba légende, biographie na yo mpe projet na yo, oyo ebimisi lokola PDF.",
    },
