    priceYourWorkDesc: {
      fr: "Combien cette pièce devrait-elle se vendre ? Partez de ce qu'elle vous a coûté (vos heures et vos matériaux) et laissez le calculateur suggérer une fourchette. Tous les prix en dollars américains, affichés aussi en euros, livres, francs suisses et shillings ougandais, aux taux de change du jour.",
      en: "What should this piece sell for? Start from what it cost you (your hours and your materials) and let the calculator suggest a range. All prices in US dollars, shown in euros, pounds, Swiss francs and Ugandan shillings too, at the day's exchange rates.",
      de: "Wofür sollte dieses Werk verkauft werden? Beginnen Sie mit dem, was es Sie gekostet hat (Ihre Stunden und Ihre Materialien) und lassen Sie den Rechner eine Preisspanne vorschlagen. Alle Preise in US-Dollar, in Euro, Pfund, Schweizer Franken und auch in ugandischen Schillingen zu den jeweiligen Wechselkursen.",
      it: "Per cosa dovrebbe vendere questo pezzo? Inizia da quello che ti costa (le tue ore e i tuoi materiali) e lascia che la calcolatrice suggerisca un intervallo. Tutti i prezzi in dollari statunitensi, indicati in euro, libbre, franchi svizzeri e scellini ugandesi anche, ai tassi di cambio del giorno.",
      es: "¿Para qué debería vender esta pieza? Comience desde lo que le costó (sus horas y sus materiales) y permita que la calculadora sugiera un rango. Todos los precios en dólares estadounidenses, mostrados en euros, libras, francos suizos y chelines ugandeses también, a los tipos de cambio del día.",
      pt: "Por quanto deve esta peça ser vendida? Comece pelo que ela lhe custou (as suas horas e os seus materiais) e deixe a calculadora sugerir um intervalo. Todos os preços em dólares americanos, mostrados também em euros, libras, francos suíços e xelins ugandeses, às taxas de câmbio do dia.",
      zh: "这件作品应该卖多少钱？从它的成本（您的工时和材料）出发，让计算器建议一个价格区间。所有价格以美元计价，同时按当日汇率显示欧元、英镑、瑞士法郎和乌干达先令。",
      ja: "この作品はいくらで売るべきですか。かかった費用（時間と材料）から始め、計算機が価格帯を提案します。すべての価格は米ドルで、ユーロ、ポンド、スイスフラン、ウガンダシリングでも、その日の為替レートで表示されます。",
      ko: "이 작품은 얼마에 팔아야 할까요? 비용(시간과 재료)에서 시작해 계산기가 범위를 제안하게 하세요. 모든 가격은 미국 달러 기준이며, 당일 환율로 유로, 파운드, 스위스 프랑, 우간다 실링으로도 표시됩니다.",
      sw: "Kazi hii inapaswa kuuzwa kwa kiasi gani? Anza kutoka gharama yake kwako (saa zako na vifaa vyako) na acha kikokotoo kipendekeze kiwango. Bei zote kwa dola za Marekani, zikionyeshwa pia kwa euro, pauni, faranga za Uswisi na shilingi za Uganda, kwa viwango vya ubadilishaji vya siku.",
      ln: "Mosala oyo esengeli kotekama na motuya nini? Banda wuta oyo etalaki yo (ba ngonga na yo mpe biloko na yo) mpe tika machine ya kotanga epesa motuya. Ba motuya nionso na ba dollar ya Amérique, emonanaka mpe na ba euro, ba livre, ba franc ya Suisse mpe ba shilling ya Uganda, na ba taux ya mokolo.",
    },
