    printStudioDesc: {
      fr: "Des supports prêts pour la production à partir de vos propres œuvres : affiches, cartels, pages de catalogue et certificats. Vraies dimensions d'impression, fonds perdus et marges de sécurité, un contrôle DPI calculé à partir des pixels réels de l'image, et un PDF de production avec traits de coupe.",
      en: "Production-ready materials from your own artworks: posters, wall labels, catalogue pages and certificates. Real print dimensions, bleed and safe margins, a DPI check computed from the image's actual pixels, and a production PDF with crop marks.",
      de: "Produktionsfertige Materialien aus eigenen Werken: Plakate, Wandtexte, Katalogseiten und Zertifikate. Echte Druckmaße, Beschnitt und sichere Ränder, ein DPI-Check berechnet aus den tatsächlichen Pixeln des Bildes und ein Produktions-PDF mit Schnittmarken.",
      it: "Materiali pronti alla produzione dalle proprie opere: poster, etichette a parete, pagine di catalogo e certificati. Dimensioni di stampa reali, margini sanguinati e sicuri, un controllo DPI calcolato dai pixel effettivi dell'immagine, e un PDF di produzione con segni di ritaglio.",
      es: "Materiales de producción de sus propias obras: carteles, etiquetas de pared, páginas de catálogo y certificados. Dimensiones de impresión reales, márgenes sangrados y seguros, un cheque DPI computed de los píxeles reales de la imagen, y un PDF de producción con marcas de cultivo.",
      pt: "Materiais prontos para produção a partir das suas próprias obras: cartazes, cartazes de parede, páginas de catálogo e certificados. Dimensões reais de impressão, sangria e margens de segurança, uma verificação de DPI calculada a partir dos píxeis reais da imagem, e um PDF de produção com marcas de corte.",
      zh: "根据您自己的作品制作可直接用于生产的材料：海报、墙面标签、目录页和证书。真实的印刷尺寸、出血和安全边距、根据图片实际像素计算的 DPI 检查，以及带裁切标记的生产 PDF。",
      ja: "自分の作品から、制作に使える素材を作ります。ポスター、壁の説明文、カタログページ、証明書。実際の印刷サイズ、塗り足し、安全余白、画像の実際のピクセルから計算したDPIチェック、トンボ付きの制作PDF。",
      ko: "내 작품으로 제작용 자료를 만드세요. 포스터, 벽 라벨, 카탈로그 페이지, 증명서. 실제 인쇄 크기, 여백, 안전 마진, 이미지의 실제 픽셀에서 계산한 DPI 검사, 자르기 표시가 있는 제작용 PDF.",
      sw: "Nyenzo tayari kwa uzalishaji kutoka kazi zako mwenyewe: mabango, lebo za ukuta, kurasa za katalogi na vyeti. Vipimo halisi vya uchapishaji, ukingo wa ziada na pambizo salama, ukaguzi wa DPI uliohesabiwa kutoka pikseli halisi za picha, na PDF ya uzalishaji yenye alama za kukata.",
      ln: "Biloko ebongi mpo na kosala wuta misala na yo moko: ba affiche, ba étiquette ya mur, ba page ya catalogue mpe ba-certificat. Bonene ya solo ya kobimisa, ba marge mpe ba marge ya bokebi, kotala ya DPI oyo etangami wuta ba pixel ya solo ya foto, mpe PDF ya kosala na ba elembo ya kokata.",
    },
