    portfolioPdfDesc: {
      fr: "Créez affiches, publications, CV, invitations et présentations dans l’éditeur Atelier : 8 modèles originaux, textes, formes, images, calques, pages multiples. Puis exportez en vrai PDF vectoriel, JPG ou PNG haute résolution.",
      en: "Create posters, posts, CVs, invitations and presentations in the Atelier editor: 8 original templates, text, shapes, images, layers, multiple pages. Then export a real vector PDF, or high-resolution JPG/PNG.",
      de: "Erstellen Sie Poster, Posts, Lebensläufe, Einladungen und Präsentationen im Atelier-Editor: 8 Originalvorlagen, Text, Formen, Bilder, Schichten, mehrere Seiten. Exportieren Sie dann ein echtes Vektor-PDF oder hochauflösendes JPG/PNG.",
      it: "Crea poster, post, CV, inviti e presentazioni nell'editor Atelier: 8 modelli originali, testo, forme, immagini, strati, pagine multiple. Quindi esportare un vero vettore PDF, o ad alta risoluzione JPG/PNG.",
      es: "Crear carteles, postes, CVs, invitaciones y presentaciones en el editor Atelier: 8 plantillas originales, texto, formas, imágenes, capas, múltiples páginas. Luego exporta un PDF vectorial real, o JPG/PNG de alta resolución.",
      pt: "Crie cartazes, publicações, CV, convites e apresentações no editor Atelier: 8 modelos originais, texto, formas, imagens, camadas, várias páginas. Depois exporte um PDF vetorial real, ou JPG/PNG de alta resolução.",
      zh: "在 Atelier 编辑器中创建海报、帖子、简历、邀请函和演示文稿：8 个原创模板、文本、形状、图片、图层、多个页面。然后导出真正的矢量 PDF，或高分辨率 JPG/PNG。",
      ja: "Atelierエディタでポスター、投稿、CV、招待状、プレゼンテーションを作ります。8つのオリジナルテンプレート、テキスト、図形、画像、レイヤー、複数ページ。その後、本物のベクターPDF、または高解像度JPG/PNGで書き出します。",
      ko: "Atelier 편집기에서 포스터, 게시물, 이력서, 초대장, 프레젠테이션을 만드세요. 8개의 오리지널 템플릿, 텍스트, 도형, 이미지, 레이어, 여러 페이지. 그런 다음 실제 벡터 PDF나 고해상도 JPG/PNG로 내보내세요.",
      sw: "Tengeneza mabango, machapisho, CV, mialiko na mawasilisho kwenye kihariri cha Atelier: templeti 8 za asili, maandishi, maumbo, picha, tabaka, kurasa nyingi. Kisha hamisha PDF halisi ya vekta, au JPG/PNG ya ubora wa juu.",
      ln: "Sala ba affiche, ba publication, ba CV, ba invitation mpe ba présentation na mobongisi ya Atelier: ba modèle 8 ya liboso, makomi, ba lolenge, foto, ba couche, ba page mingi. Na sima bimisa PDF ya solo ya vecteur, to JPG/PNG ya résolution ya likolo.",
    },
