    teamsDesc: {
      fr: "Partagez une exposition avec une équipe, parlez-en dans les commentaires, demandez une relecture et approuvez-la ensemble. Les propriétaires invitent, les éditeurs partagent et modifient, les lecteurs lisent, et chaque autorisation est vérifiée sur le serveur, pas seulement dans les boutons.",
      en: "Share an exhibition with a team, talk about it in comments, ask for a review and approve it together. Owners invite, editors share and edit, viewers read, and every permission is checked on the server, not just in the buttons.",
      de: "Teilen Sie eine Ausstellung mit einem Team, sprechen Sie in Kommentaren darüber, bitten Sie um eine Überprüfung und genehmigen Sie sie gemeinsam. Besitzer laden ein, Redakteure teilen und bearbeiten, Zuschauer lesen und jede Berechtigung wird auf dem Server überprüft, nicht nur in den Buttons.",
      it: "Condividere una mostra con un team, parlarne in commenti, chiedere una recensione e approvarla insieme. I proprietari invitano, gli editor condividono e modificano, gli spettatori leggono, e ogni autorizzazione viene controllata sul server, non solo nei pulsanti.",
      es: "Compartir una exposición con un equipo, hablar de ello en comentarios, pedir una revisión y aprobarla juntos. Los propietarios invitan, los editores comparten y editan, los espectadores leen, y cada permiso se revisa en el servidor, no sólo en los botones.",
      pt: "Partilhe uma exposição com uma equipa, fale sobre ela nos comentários, peça uma revisão e aprovem-na juntos. Os proprietários convidam, os editores partilham e editam, os leitores leem, e cada autorização é verificada no servidor, não só nos botões.",
      zh: "与团队共享展览，在评论中讨论它，请求审阅并共同批准。所有者邀请，编辑者共享和编辑，查看者阅读，每项权限都在服务器上验证，而不仅仅是在按钮中。",
      ja: "展示をチームと共有し、コメントで話し合い、レビューを依頼して一緒に承認します。所有者は招待し、編集者は共有して編集し、閲覧者は読みます。すべての権限はボタンだけでなく、サーバーで確認されます。",
      ko: "전시를 팀과 공유하고, 댓글로 이야기하고, 검토를 요청하고, 함께 승인하세요. 소유자가 초대하고, 편집자가 공유하고 수정하고, 보는 사람은 읽고, 모든 권한은 버튼이 아니라 서버에서 확인됩니다.",
      sw: "Shiriki onyesho na timu, zungumza kulihusu kwenye maoni, omba mapitio na uyakubali pamoja. Wamiliki hualika, wahariri hushiriki na kuhariri, watazamaji husoma, na kila ruhusa huangaliwa kwenye seva, si kwenye vitufe tu.",
      ln: "Kabola bimiseli na ekipi, solola na tina na yango na ba likanisi, senga kotala mpe ndima yango elongo. Ba mokolo babengaka, ba mobongisi bakabolaka mpe babongolaka, ba motali batalaka, mpe ndimbola moko na moko etalami na serveur, na ba bouton kaka te.",
    },
