    videoGeneratorDesc: {
      fr: "Transformez une exposition en vidéo pour Reels, votre fil ou YouTube : définissez les plans (marches de caméra, gros plans sur les œuvres, cartons de titre et de texte), puis enregistrez la vraie salle 3D dans votre navigateur. Pas de ferme de rendu : la vidéo est capturée en direct, en temps réel, et téléchargée en fichier .webm.",
      en: "Turn an exhibition into a video for Reels, your feed or YouTube: define the shots (camera walks, artwork close-ups, title and statement cards), then record the real 3D room in your browser. No render farm: the video is captured live, in real time, and downloaded as a .webm file.",
      de: "Verwandeln Sie eine Ausstellung in ein Video für Reels, Ihren Feed oder YouTube: Definieren Sie die Aufnahmen (Kamerafahrten, Nahaufnahmen der Werke, Titel- und Textkarten) und nehmen Sie dann den echten 3D-Raum in Ihrem Browser auf. Keine Renderfarm: Das Video wird live in Echtzeit aufgenommen und als .webm-Datei heruntergeladen.",
      it: "Trasforma una mostra in un video per Reels, il tuo feed o YouTube: definisci le inquadrature (movimenti di sala, primi piani sulle opere, schede di titolo e di testo), poi registra la vera sala 3D nel tuo browser. Nessuna render farm: il video viene catturato dal vivo, in tempo reale, e scaricato come file .webm.",
      es: "Convierte una exposición en un vídeo para Reels, tu feed o YouTube: define los planos (recorridos de cámara, primeros planos de las obras, tarjetas de título y de texto) y luego graba la sala 3D real en tu navegador. Sin granja de renderizado: el vídeo se captura en directo, en tiempo real, y se descarga como archivo .webm.",
      pt: "Transforme uma exposição num vídeo para Reels, o seu feed ou o YouTube: defina os planos (caminhadas de câmara, grandes planos das obras, cartões de título e de texto), depois grave a sala 3D real no seu navegador. Sem quinta de renderização: o vídeo é capturado em direto, em tempo real, e descarregado como ficheiro .webm.",
      zh: "将展览变成用于 Reels、动态或 YouTube 的视频：定义镜头（相机漫步、作品特写、标题和说明卡片），然后在浏览器中录制真实的 3D 展厅。无需渲染农场：视频实时录制，并下载为 .webm 文件。",
      ja: "展示をReels、フィード、YouTube用の動画にします。ショットを決め（カメラの歩行、作品のクローズアップ、タイトルと説明のカード）、ブラウザで本物の3Dの部屋を録画します。レンダーファームは不要です。動画はライブで、リアルタイムに撮影され、.webmファイルとしてダウンロードされます。",
      ko: "전시를 Reels, 피드, YouTube용 비디오로 바꾸세요. 샷(카메라 걷기, 작품 클로즈업, 제목과 설명 카드)을 정한 뒤 브라우저에서 실제 3D 전시실을 녹화하세요. 렌더 팜은 없습니다. 비디오는 실시간으로 캡처되어 .webm 파일로 다운로드됩니다.",
      sw: "Geuza onyesho kuwa video kwa Reels, mlisho wako au YouTube: fafanua picha (matembezi ya kamera, picha za karibu za kazi, kadi za kichwa na taarifa), kisha rekodi chumba halisi cha 3D kwenye kivinjari chako. Hakuna shamba la kuchora: video hunaswa moja kwa moja, kwa wakati halisi, na kupakuliwa kama faili ya .webm.",
      ln: "Bongola bimiseli na video mpo na Reels, fil na yo to YouTube: bongisa ba plan (ba kotambola ya caméra, ba foto ya pene ya misala, ba carte ya kombo mpe ya makomi), na sima zwama ndako ya solo ya 3D na navigateur na yo. Ferme ya rendu ezali te: video ezwamaka na bomoi, na ntango ya solo, mpe ekitaka lokola fichier .webm.",
    },
